 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 20→func init() {
 21→	agent.Register(agent.AgentNameCursor, NewCursorAgent)
 22→}
 23→
 24→// CursorAgent implements the Agent interface for Cursor.
 25→//
 26→//nolint:revive // CursorAgent is clearer than Agent in this context
 27→type CursorAgent struct{}
 28→
 29→// NewCursorAgent creates a new Cursor agent instance.
 30→func NewCursorAgent() agent.Agent {
 31→	return &CursorAgent{}
 32→}
 33→
 34→// Name returns the agent registry key.
 35→func (c *CursorAgent) Name() types.AgentName {
 36→	return agent.AgentNameCursor
 37→}
 38→
 39→// Type returns the agent type identifier.
 40→func (c *CursorAgent) Type() types.AgentType {
 41→	return agent.AgentTypeCursor
 42→}
 43→
 44→// Description returns a human-readable description.
 45→func (c *CursorAgent) Description() string {
 46→	return "Cursor - AI-powered code editor"
 47→}
 48→
 49→func (c *CursorAgent) IsPreview() bool { return true }
 50→
 51→// DetectPresence checks if Cursor is configured in the repository.
 52→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 53→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 54→	if err != nil {
 55→		worktreeRoot = "."
 56→	}
 57→
 58→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 59→	if _, err := os.Stat(cursorDir); err == nil {
 60→		return true, nil
 61→	}
 62→	return false, nil
 63→}
 64→
 65→// GetSessionID extracts the session ID from hook input.
 66→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 67→	return input.SessionID
 68→}
 69→
 70→// ResolveSessionFile returns the path to a Cursor session file.
 71→// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
 72→// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
 73→// We prefer nested if the file OR directory exists (the directory may be created
 74→// before the file is flushed), otherwise fall back to flat.
 75→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 76→	nestedDir := filepath.Join(sessionDir, agentSessionID)
 77→	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
 78→	if _, err := os.Stat(nested); err == nil {
 79→		return nested
 80→	}
 81→	// IDE creates the directory before the transcript file — predict nested path.
 82→	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
 83→		return nested
 84→	}
 85→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 86→}
 87→
 88→// ProtectedDirs returns directories that Cursor uses for config/state.
 89→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 90→
 91→// GetSessionDir returns the directory where Cursor stores session transcripts.
 92→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 93→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 94→		return override, nil
 95→	}
 96→
 97→	homeDir, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return "", fmt.Errorf("failed to get home directory: %w", err)
100→	}
101→
102→	projectDir := sanitizePathForCursor(repoPath)
103→	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
104→}
105→
106→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
107→// Note: ModifiedFiles is left empty because Cursor's transcript does not contain
108→// tool_use blocks for file detection. TranscriptAnalyzer extracts prompts and
109→// summaries; file detection relies on git status.
110→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
111→	if input.SessionRef == "" {
112→		return nil, errors.New("session reference (transcript path) is required")
113→	}
114→
115→	data, err := os.ReadFile(input.SessionRef)
116→	if err != nil {
117→		return nil, fmt.Errorf("failed to read transcript: %w", err)
118→	}
119→
120→	return &agent.AgentSession{
121→		SessionID:  input.SessionID,
122→		AgentName:  c.Name(),
123→		SessionRef: input.SessionRef,
124→		StartTime:  time.Now(),
125→		NativeData: data,
126→	}, nil
127→}
128→
129→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
130→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
131→	if session == nil {
132→		return errors.New("session is nil")
133→	}
134→
135→	if session.AgentName != "" && session.AgentName != c.Name() {
136→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
137→	}
138→
139→	if session.SessionRef == "" {
140→		return errors.New("session reference (transcript path) is required")
141→	}
142→
143→	if len(session.NativeData) == 0 {
144→		return errors.New("session has no native data to write")
145→	}
146→
147→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
148→		return fmt.Errorf("failed to write transcript: %w", err)
149→	}
150→
151→	return nil
152→}
153→
154→// FormatResumeCommand returns an instruction to resume a Cursor session.
155→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
156→func (c *CursorAgent) FormatResumeCommand(_ string) string {
157→	return "Open this project in Cursor to continue the session."
158→}
159→
160→// sanitizePathForCursor converts a path to Cursor's project directory format.
161→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
162→
163→func sanitizePathForCursor(path string) string {
164→	path = strings.TrimLeft(path, "/")
165→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
166→}
167→
168→// ChunkTranscript splits a JSONL transcript at line boundaries.
169→func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
170→	chunks, err := agent.ChunkJSONL(content, maxSize)
171→	if err != nil {
172→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
173→	}
174→	return chunks, nil
175→}
176→
177→// ReassembleTranscript concatenates JSONL chunks with newlines.
178→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
179→	return agent.ReassembleJSONL(chunks), nil
180→}
