 16→// intFromJSON safely converts a json.Number to int64, returning 0 for
 17→// empty or non-numeric values (hook payloads may omit optional fields).
 18→func intFromJSON(n json.Number) int64 {
 19→	v, err := n.Int64()
 20→	if err != nil {
 21→		return 0
 22→	}
 23→	return v
 24→}
 25→
 26→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 27→// Returns nil if the hook has no lifecycle significance.
 28→func (c *CursorAgent) ParseHookEvent(ctx context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 29→	switch hookName {
 30→	case HookNameSessionStart:
 31→		return c.parseSessionStart(stdin)
 32→	case HookNameBeforeSubmitPrompt:
 33→		return c.parseTurnStart(ctx, stdin)
 34→	case HookNameStop:
 35→		return c.parseTurnEnd(ctx, stdin)
 36→	case HookNameSessionEnd:
 37→		return c.parseSessionEnd(ctx, stdin)
 38→	case HookNamePreCompact:
 39→		return c.parsePreCompact(stdin)
 40→	case HookNameSubagentStart:
 41→		return c.parseSubagentStart(stdin)
 42→	case HookNameSubagentStop:
 43→		return c.parseSubagentStop(stdin)
 44→	default:
 45→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 46→	}
 47→}
 48→
 49→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 50→func (c *CursorAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 51→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 52→	if err != nil {
 53→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 54→	}
 55→	return data, nil
 56→}
