 58→// --- Internal hook parsing functions ---
 59→
 60→// resolveTranscriptRef returns the transcript path from the hook input, or computes
 61→// it dynamically when the hook doesn't provide one (Cursor CLI pattern).
 62→func (c *CursorAgent) resolveTranscriptRef(ctx context.Context, conversationID, rawPath string) string {
 63→	if rawPath != "" {
 64→		return rawPath
 65→	}
 66→
 67→	repoRoot, err := paths.WorktreeRoot(ctx)
 68→	if err != nil {
 69→		logging.Warn(ctx, "cursor: failed to get worktree root for transcript resolution", "err", err)
 70→		return ""
 71→	}
 72→
 73→	sessionDir, err := c.GetSessionDir(repoRoot)
 74→	if err != nil {
 75→		logging.Warn(ctx, "cursor: failed to get session dir for transcript resolution", "err", err)
 76→		return ""
 77→	}
 78→
 79→	return c.ResolveSessionFile(sessionDir, conversationID)
 80→}
