 82→func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
 83→	raw, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
 84→	if err != nil {
 85→		return nil, err
 86→	}
 87→	return &agent.Event{
 88→		Type:       agent.SessionStart,
 89→		SessionID:  raw.ConversationID,
 90→		SessionRef: raw.TranscriptPath,
 91→		Timestamp:  time.Now(),
 92→	}, nil
